// Redrock Canyon entry point for shared/world/templates.js. The 768 x 80 x 768
// desert canyon is generated by shared/world/redrock-sites/generate.js from
// the pure terrain in shared/world/redrock-terrain.js.
import { generateRedrockInto as generate } from './redrock-sites/generate.js';

/** Fill `blocks` (y/z/x) with the complete Redrock Canyon world. */
export function generateRedrockInto(world, blocks, heights) {
  generate(world, blocks, heights);
}
